namespace App\Services;use App\Models\{TransportPassenger,TransportRoute,TransportService};use Carbon\Carbon;use Illuminate\Support\Facades\DB;use Illuminate\Support\Str;use Illuminate\Validation\ValidationException;
class TransportSchedulingService{public function __construct(private TransportSchedulingConflictService$conflicts,private TransportAuditService$audit){}public function create(array$data,int$company,int$user):TransportService{$route=TransportRoute::forCompany($company)->where('status','active')->findOrFail($data['transport_route_id']);[$start,$end]=$this->dates($data);$conflicts=$this->conflicts->conflicts($company,$start,$end,$data['planned_vehicle_id']??null,$data['planned_driver_id']??null,$data['planned_monitor_id']??null);if($conflicts)throw ValidationException::withMessages(['service'=>'Conflicto de programación en: '.implode(', ',$conflicts).'.']);return DB::transaction(function()use($data,$company,$user,$route,$start,$end){$s=TransportService::create($data+['company_id'=>$company,'uuid'=>(string)Str::uuid(),'service_date'=>$start->toDateString(),'scheduled_start_at'=>$start,'scheduled_arrival_at'=>$end,'route_name_snapshot'=>$route->name,'origin_snapshot'=>$route->origin,'destination_snapshot'=>$route->destination,'status'=>'scheduled','generation_source'=>'manual','created_by'=>$user]);$this->audit->record($company,'transport_service_created','service',$s->id,$user);return$s;});}public function reschedule(TransportService$s,array$data,int$user):void{if(!in_array($s->status,['draft','scheduled','ready']))throw ValidationException::withMessages(['status'=>'Este servicio ya no permite reprogramación.']);[$start,$end]=$this->dates($data);$conflicts=$this->conflicts->conflicts($s->company_id,$start,$end,$data['planned_vehicle_id']??null,$data['planned_driver_id']??null,$data['planned_monitor_id']??null,$s->id);if($conflicts)throw ValidationException::withMessages(['service'=>'Conflicto de programación en: '.implode(', ',$conflicts).'.']);$old=$s->only(['service_date','scheduled_start_at','scheduled_arrival_at','planned_vehicle_id','planned_driver_id','planned_monitor_id','status']);DB::transaction(function()use($s,$data,$start,$end,$old,$user){$s->update($data+['service_date'=>$start->toDateString(),'scheduled_start_at'=>$start,'scheduled_arrival_at'=>$end,'status'=>'scheduled','passenger_snapshot_status'=>'pending','updated_by'=>$user]);$s->changes()->create(['change_type'=>'rescheduled','old_data'=>$old,'new_data'=>$s->fresh()->only(array_keys($old)),'reason'=>$data['reason'],'changed_by'=>$user,'changed_at'=>now()]);$this->audit->record($s->company_id,'transport_service_rescheduled','service',$s->id,$user);});}public function cancel(TransportService$s,string$reason,int$user):void{if($s->status==='cancelled')throw ValidationException::withMessages(['status'=>'El servicio ya está cancelado.']);DB::transaction(function()use($s,$reason,$user){$old=['status'=>$s->status];$s->update(['status'=>'cancelled','cancellation_reason'=>$reason,'cancelled_at'=>now(),'cancelled_by'=>$user,'updated_by'=>$user]);$s->changes()->create(['change_type'=>'cancelled','old_data'=>$old,'new_data'=>['status'=>'cancelled'],'reason'=>$reason,'changed_by'=>$user,'changed_at'=>now()]);$this->audit->record($s->company_id,'transport_service_cancelled','service',$s->id,$user);});}public function addPassenger(TransportService$s,TransportPassenger$p,string$reason,int$user):void{if($s->passenger_snapshot_status==='frozen'&&$s->status==='cancelled')throw ValidationException::withMessages(['passenger'=>'No se puede modificar un servicio cancelado.']);abort_unless($p->company_id===$s->company_id,404);$s->passengers()->updateOrCreate(['transport_passenger_id'=>$p->id],['passenger_name_snapshot'=>$p->name,'group_snapshot'=>$p->grade_group,'expected'=>true,'status'=>'expected','added_manually'=>true,'added_reason'=>$reason,'added_by'=>$user]);$this->audit->record($s->company_id,'transport_service_passenger_added','service',$s->id,$user,['passenger_id'=>$p->id]);}public function excludePassenger(TransportService$s,int$id,string$reason,int$user):void{$row=$s->passengers()->findOrFail($id);$row->update(['expected'=>false,'status'=>'excluded','excluded_reason'=>$reason,'excluded_by'=>$user,'excluded_at'=>now()]);$this->audit->record($s->company_id,'transport_service_passenger_excluded','service',$s->id,$user,['passenger_id'=>$row->transport_passenger_id]);}private function dates(array$data):array{$start=Carbon::parse($data['scheduled_start_at']);$end=Carbon::parse($data['scheduled_arrival_at']);if($end->lte($start))throw ValidationException::withMessages(['scheduled_arrival_at'=>'La llegada prevista debe ser posterior a la salida.']);return[$start,$end];}}
